1	//! Nested logical configuration: all source/evaluation/binding work is worker-owned.
2	use flux_config::{Config, ConfigCoordinator, HelperLimits};
3	use flux_input::{BindingSet, UnmappedPolicy};
4	use std::{
5	    path::PathBuf,
6	    sync::{Arc, Condvar, Mutex},
7	    thread::JoinHandle,
8	};
9	use xkbcommon::xkb;
10	
11	type Failure = &'static str;
12	struct Prepared {
13	    desired: Config,
14	    bindings: BindingSet,
15	}
16	// Retired schema/tables and replaced live-model storage are dropped on the worker.
17	// Temporary layout clones in reconfigure/validation still drop on dispatch.
18	struct Retired {
19	    _desired: Option<Config>,
20	    _bindings: Option<BindingSet>,
21	    _layout: Option<flux_layout::Layout>,
22	}
23	#[derive(Default)]
24	struct Control {
25	    latest: u64,
26	    pending: Option<(u64, PathBuf)>,
27	    evaluation_ready: bool,
28	    completion: Option<(u64, Result<Prepared, Failure>)>,
29	    retired: Option<Retired>,
30	    closed: bool,
31	}
32	#[derive(Default)]
33	struct Shared {
34	    control: Mutex<Control>,
35	    changed: Condvar,
36	}
37	pub struct RuntimeConfig {
38	    source: PathBuf,
39	    shared: Arc<Shared>,
40	    worker: Option<JoinHandle<()>>,
41	    desired: Option<Config>,
42	    applied: Option<u64>,
43	    status: &'static str,
44	    last_error: Option<Failure>,
45	}
46	impl RuntimeConfig {
47	    fn new(
48	        source: PathBuf,
49	        helper: PathBuf,
50	        keymap: String,
51	        ping: calloop::ping::Ping,
52	    ) -> std::io::Result<Self> {
53	        let shared = Arc::new(Shared::default());
54	        let notified = shared.clone();
55	        let coordinator = ConfigCoordinator::new(helper, HelperLimits::default(), move || {
56	            notified
57	                .control
58	                .lock()
59	                .unwrap_or_else(|e| e.into_inner())
60	                .evaluation_ready = true;
61	            notified.changed.notify_one();
62	        })?;
63	        let control = shared.clone();
64	        let worker = std::thread::Builder::new()
65	            .name("flux-config-prepare".into())
66	            .spawn(move || run_worker(control, coordinator, keymap, ping))?;
67	        Ok(Self {
68	            source,
69	            shared,
70	            worker: Some(worker),
71	            desired: None,
72	            applied: None,
73	            status: "pending",
74	            last_error: None,
75	        })
76	    }
77	    fn request(&mut self) -> Result<u64, Failure> {
78	        let mut c = self
79	            .shared
80	            .control
81	            .lock()
82	            .unwrap_or_else(|e| e.into_inner());
83	        if c.closed || self.worker.as_ref().is_none_or(|w| w.is_finished()) {
84	            return Err("configuration worker is unavailable");
85	        }
86	        let generation = c
87	            .latest
88	            .checked_add(1)
89	            .ok_or("configuration generation exhausted")?;
90	        c.latest = generation;
91	        // Only a bounded path is replaced here. Old large completions stay on
92	        // the worker until it observes the superseding request.
93	        c.pending = Some((generation, self.source.clone()));
94	        self.status = "pending";
95	        self.last_error = None;
96	        self.shared.changed.notify_one();
97	        Ok(generation)
98	    }
99	    fn completion(&mut self) -> Option<(u64, Result<Prepared, Failure>)> {
100	        let mut c = self
101	            .shared
102	            .control
103	            .lock()
104	            .unwrap_or_else(|e| e.into_inner());
105	        if self.status != "failed" && self.worker.as_ref().is_none_or(|w| w.is_finished()) {
106	            return Some((c.latest, Err("configuration preparation worker stopped")));
107	        }
108	        if c.retired.is_some() || c.completion.as_ref()?.0 != c.latest {
109	            return None;
110	        }
111	        c.completion.take()
112	    }
113	    fn retire(&self, value: Retired) {
114	        let mut c = self
115	            .shared
116	            .control
117	            .lock()
118	            .unwrap_or_else(|e| e.into_inner());
119	        // Only dispatch fills this slot, immediately after taking a completion
120	        // which checked it empty. The worker can only empty it in between.
121	        assert!(c.retired.is_none());
122	        c.retired = Some(value);
123	        self.shared.changed.notify_one();
124	    }
125	    pub fn shutdown(&mut self) -> std::io::Result<()> {
126	        {
127	            let mut c = self
128	                .shared
129	                .control
130	                .lock()
131	                .unwrap_or_else(|e| e.into_inner());
132	            c.closed = true;
133	            self.shared.changed.notify_one();
134	        }
135	        if let Some(worker) = self.worker.take() {
136	            worker
137	                .join()
138	                .map_err(|_| std::io::Error::other("configuration preparation worker panicked"))?;
139	        }
140	        Ok(())
141	    }
142	    pub fn diagnostics(&self) -> serde_json::Value {
143	        let c = self
144	            .shared
145	            .control
146	            .lock()
147	            .unwrap_or_else(|e| e.into_inner());
148	        serde_json::json!({
149	            "requested_generation":(c.latest != 0).then(||c.latest.to_string()),
150	            "applied_generation":self.applied.map(|g|g.to_string()),
151	            "prepared_generation":c.completion.as_ref().filter(|(g,r)|*g == c.latest && r.is_ok()).map(|(g,_)|g.to_string()),
152	            "status":self.status, "last_error":self.last_error,
153	        })
154	    }
155	    pub fn applied(&self) -> bool {
156	        self.applied.is_some()
157	    }
158	}
159	impl Drop for RuntimeConfig {
160	    fn drop(&mut self) {
161	        let _ = self.shutdown();
162	    }
163	}
164	fn run_worker(
165	    shared: Arc<Shared>,
166	    mut coordinator: ConfigCoordinator,
167	    keymap: String,
168	    ping: calloop::ping::Ping,
169	) {
170	    let context = xkb::Context::new(xkb::CONTEXT_NO_ENVIRONMENT_NAMES);
171	    let map = xkb::Keymap::new_from_string(
172	        &context,
173	        keymap,
174	        xkb::KEYMAP_FORMAT_TEXT_V1,
175	        xkb::KEYMAP_COMPILE_NO_FLAGS,
