182	                c = shared.changed.wait(c).unwrap_or_else(|e| e.into_inner());
183	            }
184	            if c.closed {
185	                break;
186	            }
187	            let values = (c.pending.take(), c.retired.take(), c.evaluation_ready);
188	            c.evaluation_ready = false;
189	            values
190	        };
191	        let retired_any = retired.is_some();
192	        drop(retired);
193	        if retired_any {
194	            ping.ping();
195	        }
196	        if let Some((generation, path)) = job {
197	            // Move stale completions out before dropping them off dispatch.
198	            let old = shared
199	                .control
200	                .lock()
201	                .unwrap_or_else(|e| e.into_inner())
202	                .completion
203	                .take();
204	            drop(old);
205	            match coordinator.request_path(path) {
206	                Ok(inner) => active = Some((generation, inner)),
207	                Err(_) => publish(
208	                    &shared,
209	                    generation,
210	                    Err("configuration request could not be admitted"),
211	                    &ping,
212	                ),
213	            }
214	        }
215	        if ready
216	            && let Some(result) = coordinator.take_completion()
217	            && let Some((generation, inner)) = active
218	            && inner == result.generation
219	        {
220	            let result = result
221	                .result
222	                .map_err(|failure| match failure.kind {
223	                    flux_config::ConfigFailureKind::Io => {
224	                        "configuration source or helper I/O failed"
225	                    }
226	                    flux_config::ConfigFailureKind::Invalid => {
227	                        "configuration schema or source validation failed"
228	                    }
229	                    flux_config::ConfigFailureKind::Timeout => "configuration evaluation timed out",
230	                    flux_config::ConfigFailureKind::Helper => {
231	                        "configuration helper rejected evaluation"
232	                    }
233	                    flux_config::ConfigFailureKind::Cancelled => {
234	                        "configuration evaluation cancelled"
235	                    }
236	                })
237	                .and_then(|candidate| {
238	                    let config = &candidate.config().config;
239	                    if config.layout.gaps > 1024.0 {
240	                        return Err("layout.gaps exceeds the nested model limit of 1024");
241	                    }
242	                    if config.bindings.iter().any(|b| {
243	                        matches!(
244	                            b.action,
245	                            flux_core::Action::Fullscreen { .. }
246	                                | flux_core::Action::Floating { .. }
247	                                | flux_core::Action::Overview { .. }
248	                                | flux_core::Action::Lock
249	                        )
250	                    }) {
251	                        return Err("a binding action is unavailable in the nested backend");
252	                    }
253	                    let bindings = BindingSet::compile(
254	                        &config.bindings,
255	                        map.as_ref()
256	                            .ok_or("seat keymap could not be reconstructed")?,
257	                        UnmappedPolicy::Reject,
258	                    )
259	                    .map_err(|_| "configuration bindings failed seat-keymap validation")?;
260	                    Ok(Prepared {
261	                        desired: config.clone(),
262	                        bindings,
263	                    })
264	                });
265	            publish(&shared, generation, result, &ping);
266	        }
267	    }
268	    // No join or large source/schema/table destruction runs during dispatch.
269	    let _ = coordinator.shutdown();
270	    let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
271	    c.pending = None;
272	    c.completion = None;
273	    c.retired = None;
274	}
275	fn publish(
276	    shared: &Shared,
277	    generation: u64,
278	    value: Result<Prepared, Failure>,
279	    ping: &calloop::ping::Ping,
280	) {
281	    let old = {
282	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
283	        if c.closed || c.latest != generation {
284	            return;
285	        }
286	        c.completion.replace((generation, value))
287	    };
288	    drop(old);
289	    ping.ping();
290	}
