328	        if self.stopping
329	            || self.shutdown_deadline.is_some()
330	            || self
331	                .seat
332	                .get_keyboard()
333	                .is_some_and(|k| !k.pressed_keys().is_empty() || k.is_grabbed())
334	            || self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
335	            || !self.pointer_presses.is_empty()
