340	            return;
341	        };
342	        if let Some((generation, result)) = config.completion() {
343	            match result {
344	                Err(error) => {
345	                    config.status = "failed";
346	                    config.last_error = Some(error);
347	                    self.bump_sequence();
348	                }
349	                Ok(prepared) => {
350	                    let mut layout = self.layout.clone();
351	                    if layout
352	                        .reconfigure(prepared.desired.layout.gaps, prepared.desired.layout.mode)
353	                        .is_err()
354	                    {
355	                        config.status = "failed";
356	                        config.last_error =
357	                            Some("configuration layout would invalidate live geometry");
358	                        config.retire(Retired {
359	                            _desired: Some(prepared.desired),
360	                            _bindings: Some(prepared.bindings),
361	                            _layout: Some(layout),
362	                        });
363	                    } else if self.sequence == u64::MAX {
364	                        config.status = "failed";
365	                        config.last_error = Some("state sequence exhausted");
366	                        config.retire(Retired {
367	                            _desired: Some(prepared.desired),
368	                            _bindings: Some(prepared.bindings),
369	                            _layout: Some(layout),
370	                        });
371	                    } else {
372	                        let old = Retired {
373	                            _desired: config.desired.replace(prepared.desired),
374	                            _bindings: Some(std::mem::replace(
375	                                &mut self.bindings,
376	                                prepared.bindings,
377	                            )),
378	                            _layout: Some(std::mem::replace(&mut self.layout, layout)),
379	                        };
380	                        config.applied = Some(generation);
