382	                        config.last_error = None;
383	                        config.retire(old);
384	                        self.relayout();
385	                        self.restore_keyboard_focus();
386	                    }
387	                    self.bump_sequence();
388	                }
389	            }
390	        }
391	        self.config = Some(config);
392	    }
