pub fn is_empty(&self) -> bool {
    self.members.is_empty()
}
pub fn viewport(&self) -> Size {
    self.viewport
}
pub fn camera(&self) -> Camera {
    match self.mode {
        LayoutMode::Strip => self.strip_camera,
        LayoutMode::Canvas => self.canvas_camera,
    }

